import pathlib,json,statistics,subprocess,os,sys,shutil,runpy
B=pathlib.Path('/data/mini_linq-wt/baseline-1106/target/baseline-1106')
rows=json.loads((B/'samples.json').read_text()); selected=[]
for name in sorted({r['kernel'] for r in rows if r.get('suite','').startswith('tpch-')}):
 for config in ['default','par']:
  s=[r for r in rows if r.get('suite')=='tpch-'+config and r.get('kernel')==name]
  ratio=statistics.median(r['value'] for r in s if r['side']=='current')/statistics.median(r['value'] for r in s if r['side']=='reference')
  if .95<=ratio<=1.05:selected.append((name,config))
(B/'layout-selection.json').write_text(json.dumps(selected))
if sys.argv[1]=='build':
 for name in sorted({n for n,c in selected}):
  crate=B/'reference/crates'/name
  env=dict(os.environ,CARGO_TARGET_DIR=str(B/'reference/target'))
  subprocess.run([str(B/'bin/cargo'),'rustc','--release','--locked','--offline','--manifest-path',str(crate/'Cargo.toml'),'--','-C','link-arg=-Wl,--shuffle-sections=*=42'],env=env,check=True)
  shutil.copy(B/'reference/target/release'/('tpch-derived-'+name),crate/'layout-worker')
else:
 sys.argv=[str(B/'measure.py'),'layout'];ns=runpy.run_path(str(B/'measure.py'))
 sample=ns['sample'];tmp=ns['TMP'];records=ns['records'];save=ns['save'];c=ns['c']
 for name,config in selected:
  for pair in range(5):
   for side in (['reference','shuffled'] if pair%2==0 else ['shuffled','reference']):
    label=f'layout-{name}-{config}-{pair}-{side}'
    if any(r['id']==label for r in records):continue
    metrics=tmp/'metrics.json';answers=tmp/'answers.json'
    cmd=[B/'reference/crates'/name/('timing-worker' if side=='reference' else 'layout-worker'),tmp/'data'/name,config,'3',answers,metrics,B/'current/raw'/name/'oracle.json']
